<?php $appointments=$ortho['appointments'] ?? []; $tasks=$ortho['tasks'] ?? []; $serviceOptions=array_column($ortho['services'] ?? $services ?? [],'name','id'); ?>
<div class="orth-section-intro"><div><h3>Controles y citas</h3><p>La agenda del consultorio reserva la disponibilidad y conserva la asistencia.</p></div><?php if(can('appointments')): ?><a class="button secondary small" href="<?= e(url('/admin/appointments?patient_id='.$case['patient_id'])) ?>">Abrir agenda <?= icon('arrow',15) ?></a><?php endif; ?></div>
<?php if($canAssist): ?><div class="orth-summary-grid"><details class="panel orth-form-panel" id="orth-schedule"><summary><?= icon('calendar',18) ?><span>Programar un control</span></summary><form method="post" class="form-grid orth-panel-body" data-orth-dirty data-loading><?php $orthoFields('schedule',$case); ?><input type="hidden" name="request_key" value="<?= e(bin2hex(random_bytes(16))) ?>"><input type="hidden" name="dentist_id" value="<?= (int)$case['dentist_id'] ?>"><?php field('date','Fecha del control',$case['next_control'] ?? date('Y-m-d'),'date',true,'min="'.date('Y-m-d').'"'); field('time','Hora','','time'); ?><label class="full">Profesional<input value="<?= e($case['professional'] ?? '') ?>" readonly></label><?php choose('service_id','Servicio de la agenda',$serviceOptions); choose('status','Estado',['pending'=>'Pendiente','confirmed'=>'Confirmada'],'confirmed'); area('reason','Motivo de la visita','Control de ortodoncia',true); ?><p class="orth-help full">La agenda comprobará el horario y los cruces de citas del profesional. Una fecha de control prevista no reserva un turno.</p><button class="button full">Reservar en la agenda</button></form></details><details class="panel orth-form-panel"><summary><?= icon('plus',18) ?><span>Vincular una cita existente</span></summary><form method="post" class="form-grid orth-panel-body" data-loading><?php $orthoFields('link_appointment',$case); ?><label class="full">Cita del paciente<select name="appointment_id" required><option value="">Seleccionar cita</option><?php foreach($ortho['unlinked_appointments'] ?? [] as $appointment): ?><option value="<?= (int)$appointment['id'] ?>"><?= local_date($appointment['starts_at']) ?> · <?= e($appointment['professional'] ?? $appointment['dentist'] ?? '') ?> · <?= e(label($appointment['status'])) ?></option><?php endforeach; ?></select></label><p class="orth-help full">Solo pueden vincularse citas de este paciente y del profesional responsable del caso.</p><button class="button secondary full">Vincular cita</button></form></details></div><?php endif; ?>
<section class="panel"><div class="orth-section-heading"><h3>Agenda vinculada al expediente</h3><span class="orth-count"><?= count($appointments) ?></span></div><div class="table-wrap" role="region" tabindex="0" aria-label="Citas del caso"><table><thead><tr><th>Fecha y hora</th><th>Servicio / motivo</th><th>Profesional</th><th>Asistencia</th><th>Agenda</th></tr></thead><tbody><?php foreach($appointments as $appointment): ?><tr><td><?= local_date($appointment['starts_at'] ?? null) ?><small>Hasta <?= local_date($appointment['ends_at'] ?? null,'H:i') ?></small></td><td><?= e($appointment['service_name'] ?? $appointment['service'] ?? 'Control de ortodoncia') ?><small><?= e($appointment['reason'] ?? '') ?></small></td><td><?= e($appointment['professional'] ?? $appointment['dentist'] ?? $case['professional'] ?? '') ?></td><td><?= badge($appointment['status']) ?></td><td><?php if(can('appointments')): ?><a class="orth-link" href="<?= e(url('/admin/appointments?edit='.(int)($appointment['appointment_id'] ?? $appointment['id']))) ?>">Abrir cita</a><?php else: ?>Solo consulta<?php endif; ?></td></tr><?php endforeach; if(!$appointments): ?><tr><td colspan="5"><?php $orthoEmpty('Sin citas vinculadas','Programa un control o vincula una cita existente del paciente.','calendar'); ?></td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><div class="orth-section-heading"><div><span class="orth-kicker">SEGUIMIENTO DEL EQUIPO</span><h3>Tareas del expediente</h3></div></div><?php if($canAssist): ?><form method="post" class="form-grid orth-panel-body" data-loading><?php $orthoFields('task',$case); field('title','Acción pendiente','','text',true,'maxlength="250"'); field('due_date','Fecha prevista','','date'); choose('priority','Prioridad',['low'=>'Baja','normal'=>'Normal','high'=>'Alta','urgent'=>'Urgente'],'normal'); ?><button class="button secondary">Crear tarea</button></form><?php endif; ?><div class="orth-task-list"><?php foreach($tasks as $task): ?><div class="orth-task"><span class="orth-task-dot <?= e($task['priority'] ?? 'normal') ?>"></span><div><strong><?= e($task['title']) ?></strong><small><?= $orthoDate($task['due_date'] ?? null) ?> · <?= ($task['status'] ?? '')==='completed'?'Completada':'Pendiente' ?> · <?= e($task['author'] ?? '') ?></small></div><?php if($canAssist): ?><form method="post"><?php $orthoFields('task_status',$case); ?><input type="hidden" name="task_id" value="<?= (int)$task['id'] ?>"><input type="hidden" name="status" value="<?= ($task['status'] ?? '')==='completed'?'pending':'completed' ?>"><button class="button secondary small"><?= ($task['status'] ?? '')==='completed'?'Reabrir':'Completar' ?></button></form><?php endif; ?></div><?php endforeach; if(!$tasks): $orthoEmpty('Sin tareas registradas','Organiza aquí las acciones de seguimiento del caso.','check'); endif; ?></div></section>
